import pyomo.environ as pyo

DATA = {
    "big_M": 100000,
    # Each operation: (job, position, machine, processing_time)
    "operations": [
        (0, 0, 1, 1), (0, 1, 3, 6),
        (1, 0, 1, 4), (1, 1, 2, 2),
        (2, 0, 2, 9), (2, 1, 0, 2), (2, 2, 1, 2),
        (3, 0, 0, 5), (3, 1, 1, 7), (3, 2, 3, 6), (3, 3, 5, 3),
        (4, 0, 1, 2), (4, 1, 0, 9), (4, 2, 2, 8), (4, 3, 3, 7),
        (5, 0, 2, 4), (5, 1, 1, 8),
    ],
    "num_jobs": 6,
}


def build_model(data=None):
    d = data or DATA
    ops = d["operations"]
    big_M = d["big_M"]

    # Operation identifiers (index into ops list)
    op_ids = list(range(len(ops)))
    proc = {i: ops[i][3] for i in op_ids}
    mach = {i: ops[i][2] for i in op_ids}
    job_of = {i: ops[i][0] for i in op_ids}
    pos_of = {i: ops[i][1] for i in op_ids}

    # Precedence pairs: (prev, next) within same job
    job_ops = {}
    for i in op_ids:
        job_ops.setdefault(job_of[i], []).append(i)
    prec_pairs = []
    for j, lst in job_ops.items():
        lst_sorted = sorted(lst, key=lambda x: pos_of[x])
        for a, b in zip(lst_sorted[:-1], lst_sorted[1:]):
            prec_pairs.append((a, b))

    # Machine-sharing disjunctive pairs (unordered, distinct jobs)
    disj_pairs = []
    for a in op_ids:
        for b in op_ids:
            if a < b and mach[a] == mach[b] and job_of[a] != job_of[b]:
                disj_pairs.append((a, b))

    model = pyo.ConcreteModel()

    model.OPS = pyo.Set(initialize=op_ids)
    model.PREC = pyo.Set(initialize=prec_pairs, dimen=2)
    model.DISJ = pyo.Set(initialize=disj_pairs, dimen=2)

    model.start = pyo.Var(model.OPS, within=pyo.NonNegativeReals)
    model.makespan = pyo.Var(within=pyo.NonNegativeReals)
    model.before = pyo.Var(model.DISJ, within=pyo.Binary)

    # Precedence within a job
    def prec_rule(m, a, b):
        return m.start[b] >= m.start[a] + proc[a]
    model.precedence = pyo.Constraint(model.PREC, rule=prec_rule)

    # Disjunctive machine constraints (big-M)
    def disj_rule_ab(m, a, b):
        return m.start[b] >= m.start[a] + proc[a] - big_M * (1 - m.before[a, b])
    model.machine_ab = pyo.Constraint(model.DISJ, rule=disj_rule_ab)

    def disj_rule_ba(m, a, b):
        return m.start[a] >= m.start[b] + proc[b] - big_M * m.before[a, b]
    model.machine_ba = pyo.Constraint(model.DISJ, rule=disj_rule_ba)

    # Makespan >= completion of each operation
    def makespan_rule(m, i):
        return m.makespan >= m.start[i] + proc[i]
    model.makespan_def = pyo.Constraint(model.OPS, rule=makespan_rule)

    model.obj = pyo.Objective(expr=model.makespan, sense=pyo.minimize)

    return model


